// HasViewDisplay applies the HasEdge predicate on the "view_display" edge.
func HasViewDisplay() predicate.ViewFilterDef {
	return predicate.ViewFilterDef(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, ViewDisplayTable, ViewDisplayColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasViewDisplayWith applies the HasEdge predicate on the "view_display" edge with a given conditions (other predicates).
func HasViewDisplayWith(preds ...predicate.ViewDisplayDef) predicate.ViewFilterDef {
	return predicate.ViewFilterDef(func(s *sql.Selector) {
		step := newViewDisplayStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

