// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ViewFilterDef) predicate.ViewFilterDef {
	return predicate.ViewFilterDef(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ViewFilterDef) predicate.ViewFilterDef {
	return predicate.ViewFilterDef(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ViewFilterDef) predicate.ViewFilterDef {
	return predicate.ViewFilterDef(sql.NotPredicates(p))
}
